-- Add global competition rank in the same snapshot as detail counts.
-- CREATE OR REPLACE preserves the gateway owner and existing execute grants.
create or replace function public.read_target(p_target_id uuid,p_team_id uuid default null,p_category_id uuid default null,p_cursor text default null,p_expected_revision text default null) returns jsonb language sql stable security definer set search_path='' as $$with s as(select * from app_private.app_state where id=1),t as materialized(select x.* from app_private.checked_target(p_target_id,p_expected_revision) x),overall as materialized(select * from app_private.rankings(null,null)),filtered as(select f.* from app_private.favorites f join app_private.participants p on p.id=f.participant_id cross join t where f.target_id=p_target_id and(p_team_id is null or p.team_id=p_team_id) and(p_category_id is null or f.category_id=p_category_id)),page as(select * from filtered where p_cursor is null or (created_at,id)<((split_part(p_cursor,'|',1))::timestamptz,(split_part(p_cursor,'|',2))::uuid) order by created_at desc,id desc limit 21),visible as(select * from page order by created_at desc,id desc limit 20) select jsonb_build_object('revision',s.revision::text,'dataEpoch',s.data_epoch,'target',app_private.target_json(t),'filteredCount',(select count(*) from filtered),'totalCount',(select count(*) from app_private.favorites where target_id=p_target_id),'overallRank',(select rnk from overall where target_id=p_target_id),'overallRankTied',exists(select 1 from overall other join overall own on other.cnt=own.cnt where own.target_id=p_target_id and other.target_id<>p_target_id),'favorites',coalesce((select jsonb_agg(app_private.favorite_json(f) order by f.created_at desc,f.id desc) from visible f),'[]'::jsonb),'nextCursor',case when(select count(*) from page)>20 then(select created_at::text||'|'||id::text from visible order by created_at,id limit 1) else null end) from s cross join t$$;
